class Solution {
  public int[] nextLargerElement(int[] arr) {
    int[] res = new int[arr.length];
    Stack<Integer> st = new Stack<>();
    Arrays.fill(res, -1);
    for (int i = 0; i < arr.length; i++) {
      while (!st.isEmpty() && arr[i] > arr[st.peek()]) {
        int idx = st.pop();
        res[idx] = arr[i];
      }
      st.push(i);
    }
    return res;
  }
}

